@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Outfit:wght@400;500;600;700;800;900&display=swap');
:root{--paper:#f5f0e5;--ink:#252c26;--muted:#85887f;--orange:#e8784b;--green:#80947a;--line:#ded9cc;--cream:#fffdf6;--mono:'DM Mono',monospace;--sans:'Outfit',sans-serif}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);min-height:100vh}.app-shell{max-width:1440px;margin:auto;padding:0 6.1vw}.topbar{height:82px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;color:var(--ink);font-size:23px;font-weight:800;letter-spacing:-1.3px;text-decoration:none}.brand-mark{width:30px;height:30px;background:var(--orange);color:white;display:grid;place-items:center;font-size:17px;border-radius:8px;letter-spacing:-1px}.brand-dot{color:var(--orange)}.top-meta,.sound-button,.eyebrow,.controls-hint,.progress-label,.menu-footer,.art-label,.game-bottom,.stage-tip,.result-kicker{font-family:var(--mono);font-size:10px;letter-spacing:1px}.top-meta{color:#8e9188;display:flex;gap:9px;align-items:center}.status-dot{height:7px;width:7px;display:inline-block;background:var(--green);border-radius:50%}.sound-button{border:1px solid var(--line);border-radius:20px;background:none;color:var(--ink);padding:10px 14px;cursor:pointer;display:flex;gap:7px;align-items:center}.sound-icon{font-size:16px;color:var(--orange)}.screen{animation:appear .5s ease both}.hero-copy{position:relative;padding-top:74px;width:49%;min-height:395px}.eyebrow{display:flex;align-items:center;gap:9px;color:#8b8b7f;margin:0 0 18px;font-size:10px}.eyebrow-line{width:24px;height:1px;background:var(--orange)}h1{font-size:clamp(54px,7vw,94px);line-height:.96;letter-spacing:-5px;margin:0;font-weight:800}h1 span{color:var(--orange)}.intro{color:#72766e;font-size:16px;line-height:1.55;margin:22px 0 25px}.hero-actions{display:flex;align-items:center;gap:18px}.primary-button{background:var(--ink);border:0;color:white;min-width:160px;padding:16px 18px;display:flex;justify-content:space-between;align-items:center;font-family:var(--mono);letter-spacing:1px;font-size:11px;cursor:pointer;transition:transform .2s,background .2s}.primary-button:hover{background:#37453a;transform:translateY(-2px)}.button-arrow{font-size:17px;color:#e98a60}.controls-hint{color:#99988e;font-size:9px}.hero-art{position:absolute;right:9.5%;top:116px;width:37%;height:330px;overflow:hidden;background:#e8e4d7;border-radius:48% 48% 0 0 / 55% 55% 0 0}.art-sun{position:absolute;width:135px;height:135px;border-radius:50%;background:#dfaa77;opacity:.8;top:33px;left:calc(50% - 68px)}.art-orbit{position:absolute;border:1px solid rgba(89,101,82,.18);border-radius:50%;width:255px;height:255px;left:calc(50% - 127px);top:-24px}.orbit-two{width:345px;height:345px;left:calc(50% - 172px);top:-69px}.art-platform{position:absolute;bottom:40px;height:70px;width:130%;left:-10%;background:#8c9a7f;border-top:5px solid #667861}.art-cube{position:absolute;width:47px;height:47px;background:#e8784b;bottom:110px;left:28%;border-radius:3px;box-shadow:6px 6px 0 rgba(101,68,53,.15);transform:rotate(-8deg);animation:bob 1s ease-in-out infinite alternate}.art-cube:before,.art-cube:after{content:'';position:absolute;background:#fff2dc;width:5px;height:5px;top:13px;border-radius:50%}.art-cube:before{left:12px}.art-cube:after{right:12px}.art-cube i{position:absolute;width:12px;height:3px;border-bottom:1px solid #fff2dc;bottom:10px;left:17px}.art-shadow{position:absolute;width:56px;height:9px;bottom:95px;left:27%;background:#69786133;border-radius:50%;filter:blur(3px)}.art-spike{position:absolute;bottom:109px;width:0;height:0;border-left:20px solid transparent;border-right:20px solid transparent;border-bottom:41px solid #434c40}.spike-a{left:57%}.spike-b{left:73%;transform:scale(.75)}.art-label{position:absolute;color:#6b7568;font-size:9px}.art-label b{color:#e8784b;font-weight:500;margin-left:6px}.label-top{right:12%;top:43px}.label-side{left:9%;top:144px;writing-mode:vertical-rl}.art-beat{position:absolute;width:4px;height:4px;border-radius:50%;background:var(--orange);bottom:167px;animation:pulse 1s infinite}.beat-one{left:22%}.beat-two{left:44%;animation-delay:.25s}.beat-three{left:84%;animation-delay:.5s}.level-section{border-top:1px solid var(--line);padding:29px 0 54px}.section-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:20px}.section-heading h2{margin:0;font-size:30px;letter-spacing:-1.3px;line-height:1}.section-heading h2 span{font:11px var(--mono);letter-spacing:0;color:#96968a;margin-left:8px}.section-heading .eyebrow{margin-bottom:9px}.progress-label{color:#99988e;font-size:9px}.level-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:10px}.level-card{position:relative;text-align:left;background:transparent;border:1px solid #dcd7ca;min-height:86px;padding:12px 13px;color:var(--ink);cursor:pointer;transition:.18s}.level-card:hover:not(:disabled){background:var(--cream);border-color:#aab29e;transform:translateY(-2px)}.level-card:disabled{cursor:default;opacity:.45}.level-card.active{background:var(--cream);border-color:var(--orange)}.level-card.done{background:#e8e9df}.level-number{font:10px var(--mono);color:var(--orange);display:block;margin-bottom:8px}.level-name{font-size:13px;font-weight:600;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.level-difficulty{display:block;color:#9a9a8f;font:9px var(--mono);margin-top:5px}.level-lock{position:absolute;right:11px;top:12px;color:#a6a69a;font-size:12px}.menu-footer{border-top:1px solid var(--line);height:54px;display:flex;align-items:center;justify-content:space-between;color:#9a9a90;font-size:9px}.hidden{display:none!important}.game-screen{padding-top:22px}.game-topbar{display:flex;align-items:center;gap:15px;margin-bottom:16px}.icon-button{width:39px;height:39px;border:1px solid var(--line);background:var(--cream);font-size:20px;color:var(--ink);cursor:pointer}.level-heading{display:flex;flex-direction:column;gap:2px}.level-heading .eyebrow{margin:0;font-size:9px}.level-heading .eyebrow b{color:var(--orange);font-weight:500}.level-heading strong{font-size:16px}.game-score{margin-left:auto;display:flex;align-items:center;gap:12px;font:11px var(--mono);color:#72766e}.progress-track{width:120px;height:4px;background:#ded9cc}.progress-track i{height:100%;width:0;display:block;background:var(--orange);transition:width .1s}.game-stage{position:relative;width:100%;height:min(61vh,520px);min-height:300px;background:#e8e4d7;overflow:hidden;border:1px solid #d8d2c3;touch-action:none;cursor:pointer}.game-stage canvas{display:block;width:100%;height:100%}.stage-tip{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);white-space:nowrap;color:#70776c;font-size:9px;pointer-events:none}.tip-key{background:#f9f6ec;padding:7px 9px;margin-right:6px;border:1px solid #d6d2c6}.game-overlay{position:absolute;inset:0;background:rgba(38,45,38,.22);display:grid;place-items:center}.result-card{background:var(--cream);width:min(360px,calc(100% - 32px));padding:30px;text-align:center;box-shadow:0 14px 40px #3332;animation:cardIn .3s ease}.result-kicker{color:var(--orange)}.result-icon{font-size:32px;color:var(--orange);margin-top:10px}.result-card h2{font-size:28px;letter-spacing:-1px;margin:3px 0 5px}.result-card p{color:#85877d;font-size:14px;margin:0 0 21px}.result-actions{display:grid;gap:10px}.result-actions .primary-button{width:100%}.text-button{background:transparent;border:0;padding:9px;font:10px var(--mono);color:#85877d;cursor:pointer}.game-bottom{display:flex;justify-content:space-between;padding:15px 2px;color:#929388;font-size:9px}.game-bottom b{color:var(--orange);font-size:14px}.game-bottom .status-dot{margin-right:6px}@keyframes appear{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}@keyframes bob{to{transform:translateY(-9px) rotate(5deg)}}@keyframes pulse{50%{transform:scale(2);opacity:.45}}@keyframes cardIn{from{transform:translateY(10px);opacity:0}to{transform:none;opacity:1}}
@media(max-width:760px){.app-shell{padding:0 20px}.topbar{height:66px}.top-meta{display:none}.hero-copy{padding-top:44px;width:100%;min-height:315px}h1{font-size:clamp(54px,13vw,78px);letter-spacing:-3.5px}.intro{font-size:14px;margin:17px 0 20px}.hero-art{right:0;top:122px;width:47%;height:220px;opacity:.75}.art-sun{width:95px;height:95px;top:22px;left:calc(50% - 47px)}.art-orbit{width:185px;height:185px;left:calc(50% - 92px);top:-14px}.orbit-two{width:250px;height:250px;left:calc(50% - 125px);top:-47px}.art-platform{bottom:27px;height:51px}.art-cube{width:34px;height:34px;bottom:78px}.art-cube:before,.art-cube:after{top:9px;width:4px;height:4px}.art-cube:before{left:8px}.art-cube:after{right:8px}.art-cube i{bottom:7px;left:12px}.art-shadow{bottom:67px}.art-spike{bottom:77px;border-left-width:15px;border-right-width:15px;border-bottom-width:30px}.art-label{font-size:8px}.label-side{top:110px}.hero-actions{position:relative;z-index:2;gap:12px}.primary-button{min-width:138px;padding:14px}.controls-hint{font-size:8px}.section-heading h2{font-size:26px}.level-grid{grid-template-columns:repeat(3,1fr);gap:8px}.level-card{min-height:77px;padding:10px}.level-name{font-size:12px}.level-section{padding:24px 0 35px}.menu-footer{font-size:8px}.game-screen{padding-top:14px}.game-stage{height:min(58vh,540px);min-height:300px}.game-topbar{gap:9px}.game-score{gap:7px}.progress-track{width:72px}.game-bottom{font-size:8px}.stage-tip{font-size:8px}}
@media(max-width:380px){.hero-art{width:43%;top:135px}.hero-copy{min-height:320px}.controls-hint{max-width:120px;line-height:1.5}.sound-button{padding:8px 10px}.level-card{padding:9px 8px}.level-name{font-size:11px}.section-heading h2 span{font-size:9px}}
@media (orientation:landscape) and (max-height:520px){.game-stage{height:62vh;min-height:210px}.game-screen{padding-top:8px}.game-topbar{margin-bottom:8px}.game-bottom{padding:8px}.hero-copy{min-height:310px}}

(() => {
  const $ = (id) => document.getElementById(id);
  const menu = $('menuScreen'), gameView = $('gameScreen'), canvas = $('gameCanvas'), ctx = canvas.getContext('2d');
  const names = ['Premiers pas','En cadence','Petit détour','À petits bonds','La clairière','Pas de côté','Double temps','Ça s’accélère','Les collines','Entre les pics','À toute allure','Pique-nique','Terrain mouvant','Tout en rythme','Le grand saut','Virage serré','Sans pause','La traversée','Dernière ligne','Maestro','Sommet'];
  const difficultyNames = ['DOUX','FACILE','FACILE','FACILE','MODÉRÉ','MODÉRÉ','MODÉRÉ','MODÉRÉ','SOUTENU','SOUTENU','SOUTENU','SOUTENU','RAPIDE','RAPIDE','RAPIDE','RAPIDE','INTENSE','INTENSE','INTENSE','EXPERT','EXPERT'];
  const colors = [
    ['#e8e4d7','#87967d','#e8784b','#434c40','#d0b181'],['#e7e2d5','#718a82','#d48b62','#3f514c','#bdc6aa'],['#eee2d5','#9a8b76','#dc7751','#514941','#d6ae88'],['#e2e8de','#81947b','#cb7958','#435147','#b9c9ae'],['#e8e4d7','#a18f77','#d37853','#504940','#d7bd93'],['#e4e6df','#788f8d','#df946a','#424d4d','#b6c4bd'],['#eee5d9','#8c8f73','#db7850','#4c4a3f','#c6bd92']
  ];
  const saved = (() => { try { return JSON.parse(localStorage.getItem('rythme-save')) || {}; } catch (_) { return {}; } })();
  let highest = Math.max(1, Math.min(21, saved.highest || 1));
  let completed = new Set(saved.completed || []);
  let bests = saved.bests || {};
  let level = 1, running = false, ended = false, won = false, raf = 0;
  let player = {x: 142, y: 0, vy: 0, size: 34, grounded: true, rotation: 0};
  let obstacles = [], world = 0, speed = 260, total = 5300, lastTime = 0, elapsed = 0, beat = 0, audioCtx = null, soundOn = false;
  let stageW = 800, stageH = 420, ground = 320, worldSeed = 1;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const pad = (n) => String(n).padStart(2, '0');
  const palette = () => colors[(level - 1) % colors.length];
  function save() { localStorage.setItem('rythme-save', JSON.stringify({highest, completed:[...completed], bests})); }

  function drawLevels() {
    const grid = $('levelGrid'); grid.innerHTML = '';
    for (let i = 1; i <= 21; i++) {
      const button = document.createElement('button');
      button.className = 'level-card' + (completed.has(i) ? ' done' : '') + (i === highest ? ' active' : '');
      button.disabled = i > highest;
      button.innerHTML = `<span class="level-number">${pad(i)}</span><span class="level-name">${names[i-1]}</span><span class="level-difficulty">${difficultyNames[i-1]}</span>${i > highest ? '<span class="level-lock">⌑</span>' : completed.has(i) ? '<span class="level-lock">✓</span>' : ''}`;
      button.addEventListener('click', () => startLevel(i)); grid.appendChild(button);
    }
    $('progressLabel').textContent = `${completed.size} / 21 TERMINÉS`;
  }
  drawLevels();

  function resize() {
    const rect = canvas.getBoundingClientRect(); if (!rect.width || !rect.height) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(rect.width * dpr); canvas.height = Math.round(rect.height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0); stageW = rect.width; stageH = rect.height; ground = stageH * .79;
    player.size = clamp(stageH * .085, 29, 39); player.x = clamp(stageW * .19, 76, 158);
    if (!running) render(0);
  }
  window.addEventListener('resize', resize);

  function makeCourse() {
    const difficulty = (level - 1) / 20;
    speed = 245 + difficulty * 155;
    total = 4900 + difficulty * 1050;
    obstacles = []; worldSeed = level * 7781;
    let x = 570, n = 0;
    while (x < total - 300) {
      const rand = random(n++);
      let count = rand > .77 + difficulty * .09 ? 2 : 1;
      if (level > 12 && rand > .91) count = 3;
      obstacles.push({x, count, w: 42, h: 38 + (random(n++) > .72 ? 7 : 0)});
      x += 350 - difficulty * 48 + random(n++) * 100;
    }
  }
  function random(n) { let t = Math.sin(worldSeed + n * 82.93) * 43758.5453; return t - Math.floor(t); }

  function startLevel(which) {
    level = which; menu.classList.add('hidden'); gameView.classList.remove('hidden');
    $('levelNumber').textContent = pad(level); $('levelName').textContent = names[level - 1];
    $('stageTip').classList.remove('hidden'); $('gameOverlay').classList.add('hidden');
    world = 0; elapsed = 0; beat = 0; lastTime = 0; ended = false; won = false; running = true;
    player.vy = 0; player.grounded = true; player.rotation = 0; player.y = 0;
    makeCourse(); resize(); updateProgress(); $('bestLabel').textContent = bests[level] ? `RECORD ${Math.round(bests[level] / total * 100)}%` : 'RECORD —';
    cancelAnimationFrame(raf); raf = requestAnimationFrame(loop);
  }
  function backToMenu() { running = false; cancelAnimationFrame(raf); gameView.classList.add('hidden'); menu.classList.remove('hidden'); drawLevels(); window.scrollTo({top:0, behavior:'smooth'}); }
  function jump() {
    if (gameView.classList.contains('hidden')) return;
    enableAudio();
    if (!running) return;
    if (player.grounded) { player.vy = -Math.sqrt(stageH) * 34; player.grounded = false; player.rotation = 0; }
  }
  $('playButton').addEventListener('click', () => startLevel(highest));
  $('backButton').addEventListener('click', backToMenu);
  $('restartButton').addEventListener('click', () => startLevel(level));
  $('resultPrimary').addEventListener('click', () => won ? (level < 21 ? startLevel(level + 1) : backToMenu()) : startLevel(level));
  $('resultSecondary').addEventListener('click', () => startLevel(level));
  $('gameStage').addEventListener('pointerdown', (e) => { if (!e.target.closest('button')) { e.preventDefault(); jump(); } });
  window.addEventListener('keydown', (e) => { if (['Space','ArrowUp','KeyW'].includes(e.code)) { e.preventDefault(); jump(); } if (e.code === 'Escape' && !gameView.classList.contains('hidden')) backToMenu(); });

  function enableAudio() {
    if (!soundOn) return;
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();
  }
  function setSound(on) {
    soundOn = on; $('soundToggle').querySelector('.sound-label').textContent = on ? 'SON ON' : 'SON OFF';
    $('soundToggle').setAttribute('aria-label', on ? 'Désactiver le son' : 'Activer le son');
    if (on) enableAudio();
  }
  $('soundToggle').addEventListener('click', () => setSound(!soundOn));
  function tone(freq, duration, type, volume, at) {
    if (!soundOn || !audioCtx) return;
    const osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
    osc.type = type; osc.frequency.setValueAtTime(freq, at); gain.gain.setValueAtTime(volume, at); gain.gain.exponentialRampToValueAtTime(.001, at + duration);
    osc.connect(gain); gain.connect(audioCtx.destination); osc.start(at); osc.stop(at + duration);
  }
  function beatSound() {
    if (!soundOn || !audioCtx) return;
    const t = audioCtx.currentTime, step = beat % 4;
    tone(step === 0 ? 105 : 720, step === 0 ? .16 : .045, step === 0 ? 'sine' : 'square', step === 0 ? .14 : .026, t);
    if (step === 2) tone(220, .10, 'triangle', .05, t);
    const notes = [392, 0, 494, 0, 587, 0, 494, 0];
    if (beat % 2 === 0 && notes[(beat / 2) % notes.length]) tone(notes[(beat / 2) % notes.length], .13, 'triangle', .035, t);
    beat++;
  }
  function loop(now) {
    if (!running) return;
    if (!lastTime) lastTime = now;
    const dt = Math.min((now - lastTime) / 1000, .035); lastTime = now;
    elapsed += dt; world += speed * dt;
    player.vy += stageH * 4.1 * dt; player.y += player.vy * dt;
    if (player.y >= 0) { player.y = 0; player.vy = 0; player.grounded = true; }
    if (!player.grounded) player.rotation += dt * 5.2;
    const beatInterval = 60 / (92 + (level - 1) * 2.3);
    if (elapsed >= beat * beatInterval) beatSound();
    updateProgress(); render(now);
    const collision = obstacles.some(o => { const sx = o.x - world, w = o.count * 42 + (o.count - 1) * 5; return sx < player.x + player.size - 5 && sx + w > player.x + 5 && -player.y > player.size * .18 && -player.y < o.h + player.size * .63; });
    if (collision) finish(false);
    else if (world >= total) finish(true);
    if (running) raf = requestAnimationFrame(loop);
  }
  function updateProgress() {
    const pct = clamp(world / total, 0, 1); $('progressPercent').textContent = `${Math.floor(pct * 100)}%`; $('progressBar').style.width = `${pct * 100}%`;
  }
  function finish(success) {
    running = false; ended = true; won = success; $('stageTip').classList.add('hidden'); $('gameOverlay').classList.remove('hidden');
    const pct = clamp(world / total, 0, 1);
    if (success) {
      completed.add(level); highest = Math.max(highest, Math.min(21, level + 1)); bests[level] = Math.max(bests[level] || 0, world); save(); drawLevels();
      $('resultKicker').textContent = 'NIVEAU VALIDÉ'; $('resultIcon').textContent = '✦'; $('resultTitle').textContent = level === 21 ? 'Tu es un maestro !' : 'Bien joué !';
      $('resultText').textContent = level === 21 ? 'Tu as traversé les 21 niveaux.' : `Niveau ${pad(level)} terminé, en cadence.`;
      $('resultPrimary').querySelector('span').textContent = level === 21 ? 'RETOUR AU MENU' : 'NIVEAU SUIVANT'; $('resultSecondary').textContent = 'REJOUER';
    } else {
      bests[level] = Math.max(bests[level] || 0, world); save();
      $('resultKicker').textContent = 'OUPS, UN PIC !'; $('resultIcon').textContent = '↗'; $('resultTitle').textContent = 'Presque !';
      $('resultText').textContent = `Tu as parcouru ${Math.floor(pct * 100)} % du niveau. Reprends le rythme.`;
      $('resultPrimary').querySelector('span').textContent = 'RECOMMENCER'; $('resultSecondary').textContent = 'REJOUER';
    }
    $('bestLabel').textContent = `RECORD ${Math.round((bests[level] || 0) / total * 100)}%`;
  }

  function render(now) {
    if (!ctx || !stageW) return;
    const [sky, grass, orange, dark, hill] = palette();
    ctx.clearRect(0, 0, stageW, stageH); ctx.fillStyle = sky; ctx.fillRect(0, 0, stageW, stageH);
    // Soft, graphic hill silhouettes
    drawHill(stageW * .72, ground - stageH * .12, stageW * .52, stageH * .21, hill, .18);
    drawHill(stageW * .2, ground - stageH * .08, stageW * .48, stageH * .16, '#b8bca7', .3);
    // warm sun and small paper-like clouds
    ctx.fillStyle = '#d9b78e'; ctx.globalAlpha = .7; ctx.beginPath(); ctx.arc(stageW * .79, stageH * .22, stageH * .085, 0, Math.PI * 2); ctx.fill(); ctx.globalAlpha = 1;
    const cloudOffset = (world * .09) % (stageW + 130);
    for (let i = 0; i < 3; i++) { const cx = ((i * stageW * .48 - cloudOffset) % (stageW + 150) + stageW + 150) % (stageW + 150) - 70; cloud(cx, stageH * (.20 + (i % 2) * .1)); }
    // Ground
    ctx.fillStyle = grass; ctx.fillRect(0, ground, stageW, stageH - ground);
    ctx.fillStyle = dark; ctx.fillRect(0, ground, stageW, 5);
    ctx.globalAlpha = .18; ctx.fillStyle = '#f9f4e8';
    const stride = 44, offset = world % stride;
    for (let x = -offset; x < stageW; x += stride) ctx.fillRect(x, ground + 22, 18, 3);
    ctx.globalAlpha = 1;
    // distant beat markers / score track
    ctx.fillStyle = '#455044'; ctx.globalAlpha = .13;
    for (let x = 20 - (world * .45 % 56); x < stageW; x += 56) ctx.fillRect(x, ground - 20, 2, 6);
    ctx.globalAlpha = 1;
    // Spikes
    for (const o of obstacles) {
      const x = o.x - world; if (x < -140 || x > stageW + 80) continue;
      for (let i = 0; i < o.count; i++) {
        const sx = x + i * 47; const h = o.h;
        ctx.beginPath(); ctx.moveTo(sx, ground); ctx.lineTo(sx + 21, ground - h); ctx.lineTo(sx + 42, ground); ctx.closePath();
        ctx.fillStyle = dark; ctx.fill(); ctx.strokeStyle = '#303a32'; ctx.lineWidth = 1; ctx.stroke();
        ctx.beginPath(); ctx.moveTo(sx + 21, ground - h); ctx.lineTo(sx + 29, ground - 16); ctx.lineTo(sx + 21, ground - 20); ctx.closePath(); ctx.fillStyle = '#778371'; ctx.fill();
      }
    }
    // Cube with a tiny expressive face
    const s = player.size, px = player.x, py = ground - s + player.y;
    ctx.save(); ctx.translate(px + s/2, py + s/2); ctx.rotate(player.grounded ? Math.sin(now * .006) * .025 : player.rotation);
    ctx.fillStyle = orange; ctx.fillRect(-s/2, -s/2, s, s);
    ctx.fillStyle = '#fff3df'; ctx.fillRect(-s*.23, -s*.12, s*.12, s*.15); ctx.fillRect(s*.11, -s*.12, s*.12, s*.15);
    ctx.strokeStyle = '#fff3df'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(-s*.17,s*.22); ctx.quadraticCurveTo(0,s*.32,s*.18,s*.2); ctx.stroke();
    ctx.restore();
    // shadow below player
    const shadowWidth = s * clamp(1 - Math.abs(player.y) / 180, .35, 1);
