    ctx.beginPath(); ctx.moveTo(stageW - move, ground);
    ctx.quadraticCurveTo(stageW + x - move, y - h * .6, stageW + x + w * .3 - move, y);
    ctx.quadraticCurveTo(stageW + x + w - move, y + h * .2, stageW * 2, ground); ctx.closePath(); ctx.fill();
